function toBoolean(value) {
  if (typeof value === 'boolean') return value;

  return ['true', '1', 'yes', 'y'].includes(
    String(value ?? '').toLowerCase().trim()
  );
}

function normalizeLanguage(value) {
  const v = String(value || '').toLowerCase().trim();

  if (['en', 'eng', 'english'].includes(v)) return 'en';
  if (['ar', 'ara', 'arabic'].includes(v)) return 'ar';
  if (['de', 'deu', 'ger', 'german'].includes(v)) return 'de';

  return v || 'other';
}

return items.map(({ json }) => {

  const jordanHint =
    toBoolean(json.jordan_relevance_hint);

  return {
    json: {
      source_channel: 'gdelt',
      source_feed: 'gdelt_gkg_v2',

      title: json.title || '',
      url: json.url || '',
      publisher: json.publisher || '',
      published_at: json.published_at || null,

      language:
        normalizeLanguage(json.gdelt_language),

      country_hint:
        jordanHint ? 'Jordan' : '',

      jordan_relevance_hint:
        jordanHint,

      snippet: '',

      author:
        json.authors || '',

      // Keep for diagnostics only.
      // Never use this directly as GIZ sentiment.
      gdelt_document_tone:
        json.gdelt_document_tone ?? null,

      access_status:
        'metadata_only',

      raw_metadata: {
        gdelt_record_id:
          json.gdelt_record_id || null,

        gdelt_locations:
          json.gdelt_locations || '',

        gdelt_organizations:
          json.gdelt_organizations || ''
      }
    }
  };
});

function stripHtml(value = '') {
  return String(value)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeLanguage(value) {
  const v = String(value || '')
    .toLowerCase()
    .trim();

  if (['en', 'eng', 'english'].includes(v)) return 'en';
  if (['ar', 'ara', 'arabic'].includes(v)) return 'ar';
  if (['de', 'deu', 'ger', 'german'].includes(v)) return 'de';

  return v || 'other';
}

function detectLanguage(text, fallback = 'other') {
  const value = String(text || '').trim();

  if (!value) {
    return normalizeLanguage(fallback);
  }

  // Arabic Unicode ranges
  const arabicChars =
    (value.match(/[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF]/g) || []).length;

  // Latin alphabet characters
  const latinChars =
    (value.match(/[A-Za-zÀ-ÖØ-öø-ÿ]/g) || []).length;

  const relevantChars =
    arabicChars + latinChars;

  if (relevantChars > 0) {
    const arabicRatio =
      arabicChars / relevantChars;

    // If a substantial amount of the visible text is Arabic,
    // classify it as Arabic regardless of which Google News feed
    // discovered it.
    if (arabicRatio >= 0.35) {
      return 'ar';
    }
  }

  // For the POC, use the configured feed hint for Latin-script content.
  return normalizeLanguage(fallback);
}

function parseDate(value) {
  if (!value) return null;

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  return date;
}

return items
  .map(({ json }) => {

    const rawTitle =
      String(json.title || '').trim();

    let title = rawTitle;

    let publisher =
      json.creator ||
      json.author ||
      '';

    /*
     * Google News often returns:
     *
     * Headline - Publisher
     *
     * Only strip this when it is present.
     */
    const titleMatch =
      rawTitle.match(/^(.*)\s+-\s+([^-]+)$/);

    if (titleMatch) {
      title = titleMatch[1].trim();

      if (!publisher) {
        publisher =
          titleMatch[2].trim();
      }
    }

    const snippet =
      stripHtml(
        json.contentSnippet ||
        json.content ||
        json.description ||
        ''
      ).slice(0, 1500);

    const combinedText =
      `${title} ${snippet}`;

    const language =
      detectLanguage(
        combinedText,
        json.language_hint
      );

    const publishedDate =
      parseDate(
        json.isoDate ||
        json.pubDate ||
        json.pubdate
      );

    const rawUrl =
      json.link ||
      json.guid ||
      '';

    const isGoogleNewsUrl =
      String(rawUrl).includes(
        'news.google.com/'
      );

    return {
      json: {
        source_channel:
          'rss',

        source_feed:
          json.source_feed ||
          'rss_unknown',

        title,

        url:
          rawUrl,

        publisher,

        published_at:
          publishedDate
            ? publishedDate.toISOString()
            : null,

        /*
         * Important:
         *
         * language is inferred from the actual article metadata,
         * NOT simply inherited from the discovery feed.
         */
        language,

        feed_language_hint:
          normalizeLanguage(
            json.language_hint
          ),

        country_hint:
          json.country_hint || '',

        jordan_relevance_hint:
          String(
            json.country_hint || ''
          ).toLowerCase() === 'jordan',

        snippet,

        author:
          json.creator ||
          json.author ||
          '',

        gdelt_document_tone:
          null,

        access_status:
          'rss_metadata',

        url_type:
          isGoogleNewsUrl
            ? 'google_news_redirect'
            : 'publisher_url',

        raw_metadata: {
          original_feed_title:
            rawTitle,

          original_feed_url:
            rawUrl
        }
      }
    };
  });

const response = items[0]?.json || {};

function firstDefined(values) {
  for (const value of values) {
    if (
      value !== undefined &&
      value !== null &&
      value !== ''
    ) {
      return value;
    }
  }

  return '';
}

function cleanModelText(value) {
  if (
    typeof value === 'object' &&
    value !== null
  ) {
    return value;
  }

  let text =
    String(value || '').trim();

  text = text
    .replace(/<think>[\s\S]*?<\/think>/gi, '')
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  const firstBrace =
    text.indexOf('{');

  const lastBrace =
    text.lastIndexOf('}');

  if (
    firstBrace > -1 &&
    lastBrace > firstBrace
  ) {
    text =
      text.slice(
        firstBrace,
        lastBrace + 1
      );
  }

  return text;
}

function extractUrl(value) {
  if (!value) return '';

  if (typeof value === 'string') {
    return value;
  }

  if (typeof value === 'object') {
    return (
      value.url ||
      value.link ||
      value.href ||
      ''
    );
  }

  return '';
}

function normalizeLanguage(value) {
  const v =
    String(value || '')
      .toLowerCase()
      .trim();

  if (['en', 'eng', 'english'].includes(v)) return 'en';
  if (['ar', 'ara', 'arabic'].includes(v)) return 'ar';
  if (['de', 'deu', 'ger', 'german'].includes(v)) return 'de';

  return v || 'other';
}

function toBoolean(value) {
  if (typeof value === 'boolean') {
    return value;
  }

  return [
    'true',
    '1',
    'yes',
    'y'
  ].includes(
    String(value ?? '')
      .toLowerCase()
      .trim()
  );
}

const rawContent = firstDefined([
  response.choices?.[0]?.message?.content,
  response.message?.content,
  response.output,
  response.text,
  response.content
]);

if (!rawContent) {
  throw new Error(
    'Perplexity returned no usable model content.'
  );
}

let parsed;

try {

  const cleaned =
    cleanModelText(rawContent);

  parsed =
    typeof cleaned === 'string'
      ? JSON.parse(cleaned)
      : cleaned;

} catch (error) {

  throw new Error(
    `Perplexity JSON parse error: ${error.message}`
  );
}

if (!Array.isArray(parsed?.articles)) {
  throw new Error(
    'Perplexity result has no articles array.'
  );
}

const citations =
  Array.isArray(response.citations)
    ? response.citations
    : [];

const searchResults =
  Array.isArray(response.search_results)
    ? response.search_results
    : Array.isArray(response.searchResults)
      ? response.searchResults
      : [];

const output = [];

for (const article of parsed.articles) {

  const citationIndex =
    Number(article.citation_index || 0);

  const citation =
    citationIndex > 0
      ? citations[citationIndex - 1]
      : null;

  const searchResult =
    citationIndex > 0
      ? searchResults[citationIndex - 1]
      : null;

  const resolvedUrl =
    extractUrl(searchResult) ||
    extractUrl(citation) ||
    extractUrl(article.url);

  if (!resolvedUrl) {
    continue;
  }

  /*
   * Important change:
   *
   * Use actual search-result date if Perplexity's
   * generated JSON omitted published_at.
   */
  const publishedAt =
    article.published_at ||
    searchResult?.date ||
    null;

  const title =
    String(
      article.title ||
      searchResult?.title ||
      ''
    ).trim();

  const snippet =
    String(
      article.relevance_reason ||
      searchResult?.snippet ||
      ''
    ).slice(0, 1500);

  output.push({
    json: {

      source_channel:
        'perplexity',

      source_feed:
        'perplexity_builtin_sonar',

      source_type:
        'web_candidate',

      title,

      url:
        resolvedUrl,

      publisher:
        String(
          article.publisher || ''
        ).trim(),

      published_at:
        publishedAt,

      language:
        normalizeLanguage(
          article.language
        ),

      country_hint:
        String(
          article.country || ''
        ).trim(),

      jordan_relevance_hint:
        toBoolean(
          article.jordan_relevance_hint
        ),

      snippet,

      author: '',

      gdelt_document_tone:
        null,

      access_status:
        article.access_status ||
        'unknown',

      perplexity_citation_index:
        citationIndex,

      perplexity_url_grounded:
        true,

      raw_metadata: {

        giz_alias_matched:
          article.giz_alias_matched || '',

        citation_index:
          citationIndex,

        citation:
          citation || null,

        search_result:
          searchResult || null
      }
    }
  });
}

return output;

function canonicalizeUrl(raw = '') {

  if (!raw) return '';

  try {

    const url =
      new URL(raw);

    for (
      const param of [
        'utm_source',
        'utm_medium',
        'utm_campaign',
        'utm_term',
        'utm_content',
        'gclid',
        'fbclid',
        'mc_cid',
        'mc_eid'
      ]
    ) {

      url.searchParams.delete(
        param
      );
    }

    url.hash = '';

    url.hostname =
      url.hostname
        .toLowerCase()
        .replace(
          /^www\./,
          ''
        );

    let result =
      url.toString();

    if (
      result.endsWith('/')
    ) {

      result =
        result.slice(
          0,
          -1
        );
    }

    return result;

  } catch {

    return String(
      raw || ''
    ).trim();
  }
}

function normalizeText(
  value = ''
) {

  return String(value)

    .toLowerCase()

    .normalize(
      'NFKD'
    )

    .replace(
      /[\u0300-\u036f]/g,
      ''
    )

    .replace(
      /[^\p{L}\p{N}]+/gu,
      ' '
    )

    .replace(
      /\s+/g,
      ' '
    )

    .trim();
}

function hostname(
  raw = ''
) {

  try {

    return new URL(raw)

      .hostname

      .toLowerCase()

      .replace(
        /^www\./,
        ''
      );

  } catch {

    return '';
  }
}

const seenUrls =
  new Set();

const seenMetadata =
  new Set();

const output =
  [];

for (
  const item of items
) {

  const json =
    {
      ...item.json
    };

  json.url =
    canonicalizeUrl(
      json.url
    );

  const titleKey =
    normalizeText(
      json.title
    ).slice(
      0,
      240
    );

  const publisherKey =
    normalizeText(
      json.publisher
    ).slice(
      0,
      100
    );

  if (!titleKey) {
    continue;
  }

  let publicationDay =
    '';

  if (
    json.published_at
  ) {

    const d =
      new Date(
        json.published_at
      );

    if (
      !Number.isNaN(
        d.getTime()
      )
    ) {

      json.published_at =
        d.toISOString();

      publicationDay =
        json.published_at
          .slice(
            0,
            10
          );
    }
  }

  // Helps dedupe when different
  // discovery sources give us
  // different URLs for the same article.
  const metadataKey =
    [
      titleKey,
      publisherKey,
      publicationDay
    ].join('|');

  if (
    json.url &&
    seenUrls.has(
      json.url
    )
  ) {
    continue;
  }

  if (
    seenMetadata.has(
      metadataKey
    )
  ) {
    continue;
  }

  if (json.url) {

    seenUrls.add(
      json.url
    );
  }

  seenMetadata.add(
    metadataKey
  );

  const host =
    hostname(
      json.url
    );

  json.is_owned =
    host === 'giz.de' ||
    host.endsWith(
      '.giz.de'
    );

  json.dedupe_key =
    metadataKey;

  json.story_cluster_key =
    titleKey;

  json.ingested_at =
    new Date()
      .toISOString();

  output.push({
    json
  });
}

return output;
